page({file:'developers.html',title:`${NAME} API — AI pricing data for agents and tools`,desc:'Free JSON/CSV endpoints, OpenAPI spec and llms.txt for AI API pricing data.',ld:[ORG_LD,{'@context':'https://schema.org','@type':'Dataset',name:`${NAME} AI API price table`,url:SITE+'/developers',license:'https://creativecommons.org/licenses/by/4.0/',dateModified:lastChecked,distribution:[{'@type':'DataDownload',encodingFormat:'application/json',contentUrl:SITE+'/api/models.json'},{'@type':'DataDownload',encodingFormat:'text/csv',contentUrl:SITE+'/api/models.csv'}]}],body:`<section class="hero"><div class="eyebrow">For developers and agents · last verified ${lastChecked}</div><h1>Pricing data, machine-readable.</h1><p class="lede"><b>Answer:</b> Free JSON and CSV of published AI API list prices under CC BY 4.0. Please attribute “Ratecard” with a link to ${SITE}/.</p></section><dl class="kv" style="margin-top:28px"><dt>All models (JSON)</dt><dd><a href="/api/models.json">/api/models.json</a></dd><dt>All models (CSV)</dt><dd><a href="/api/models.csv">/api/models.csv</a></dd><dt>Providers</dt><dd><a href="/api/providers.json">/api/providers.json</a></dd><dt>Changes</dt><dd><a href="/api/changes.json">/api/changes.json</a></dd><dt>OpenAPI 3.1</dt><dd><a href="/openapi.json">/openapi.json</a></dd><dt>LLM summary</dt><dd><a href="/llms.txt">/llms.txt</a> · <a href="/llms-full.txt">/llms-full.txt</a></dd><dt>RSS</dt><dd><a href="/rss.xml">/rss.xml</a></dd></dl><div class="panel"><h3 style="margin-top:0">Cite this</h3><pre style="white-space:pre-wrap;font-size:12px">${esc(`Ratecard AI API pricing dataset (${SITE}/api/models.json, ${SITE}/api/models.csv). License: CC BY 4.0. Please attribute "Ratecard" with a link to ${SITE}/.`)}</pre></div><p class="note">Fields: input, output, cached, batch_input, batch_output are USD per 1M tokens; null when not published. Optional long_context: {threshold,input,output,cached,batch_input,batch_output}. Every row carries source and checked (YYYY-MM-DD).</p>`});
page({file:'methodology.html',title:`Methodology | ${NAME}`,desc:'How Ratecard reads, verifies and dates AI API prices.',body:`<section class="hero"><div class="eyebrow">Methodology</div><h1>How we read a rate card.</h1></section><ol class="lede"><li>We read prices only from the provider’s own pricing page, documentation or public pricing API.</li><li>Each row records the source URL and the date we read it. If we cannot read a number, the row is marked Unverified and the price is left blank.</li><li>We show standard (pay-as-you-go, global) list prices. Models with a published long-context tier expose a long_context object (threshold + rates); the finder and calculator apply that tier when the prompt/context need exceeds the threshold. Regional, data-residency and priority variants are noted, not blended.</li><li>A weekly script snapshots every source page and diffs it against the last snapshot. Changes are confirmed by hand before entering the change log.</li><li>Gateway rows (OpenRouter) are the gateway’s own list price, which may differ from the upstream provider.</li></ol>`});
